#ifndef __NPZ2100_REGMAP
#define __NPZ2100_REGMAP

// nPZ2100 Register Map
//
// Generated by the nPZ2100 configuration tool for the nPZ2100 DK.
// Peripheral 4 (P_BANK 3, ADDRP4 = 0x48) is the AS6212 on the DK; its
// window is THRUNP4 = 0x0898 (17.2 C) to THROVP4 = 0x0DAC (27.3 C).
// The last segment holds the peripheral init commands for SRAM 0x00-0x06;
// npz2100_apply_regmap() writes it on every boot.

const unsigned char npz2100_regmap[] = {
  // ---- Global configuration registers ----
  10,         // Length
  0x05,       // Start address (IOCFG1 register)
  0x20, // IOCFG1 = 0x20
  0x5A, // IOCFG2 = 0x5A
  0xFF, // IOCFG3 = 0xFF
  0x00, // IOCFG4 = 0x00
  0x18, // IOCFG5 = 0x18
  0x0C, // SYSCFG1 = 0x0C
  0x00, // SYSCFG2 = 0x00
  0xC0, 0x03, // (TOUT_L/TOUT_H)

  // ---- Peripheral 3 ---- 
  16,         // Length
  0x1F,       // Start address (P_BANK register)
  0x02,       // (P_BANK index)
  0x01, // CFGP3 = 0x01
  0x2A, // IOP3 = 0x2A
  0x02, // MODP3 = 0x02
  0x30, 0x00, // (PERP_L3/PERP_H3)
  0x02, // NCMDP3 = 0x02
  0x01, // ADDRP3 = 0x01
  0x00, // RREGP3 = 0x00
  0xE8, 0x03, // (THROVP_L3/THROVP_H3)
  0x18, 0xFC, // (THRUNP_L3/THRUNP_H3)
  0x9C, // TWTP3 = 0x9C
  0x85, // TCFGP3 = 0x85

  // ---- Peripheral 4 ---- 
  16,         // Length
  0x1F,       // Start address (P_BANK register)
  0x03,       // (P_BANK index)
  0x01, // CFGP4 = 0x01
  0x3F, // IOP4 = 0x3F
  0x2A, // MODP4 = 0x2A
  0xF0, 0x00, // (PERP_L4/PERP_H4)
  0x02, // NCMDP4 = 0x02
  0x48, // ADDRP4 = 0x48
  0x00, // RREGP4 = 0x00
  0xAC, 0x0D, // (THROVP_L4/THROVP_H4)
  0x98, 0x08, // (THRUNP_L4/THRUNP_H4)
  0x6D, // TWTP4 = 0x6D
  0x05, // TCFGP4 = 0x05

  // ---- SRAM registers ---- 
  9,          // Length
  0x7F,       // Start address (SRAM_BANK)
  0x00,       // SRAM bank 0
  0x20, 0x10, 0x29, 0x01, 0x82, 0x02, 0xA0, // SRAM address: 0x00-06
};

#endif // __NPZ2100_REGMAP
